class RiverPuddleCleanupTest{public static void main(String[]args){int n=64;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,92));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=10;z<13;z++)for(int x=10;x<13;x++){int i=z*n+x;e.height[i]=88;e.water[i]=90;e.river[i]=1;}for(int z=30;z<34;z++)for(int x=20;x<60;x++){int i=z*n+x;e.height[i]=88;e.water[i]=90;e.river[i]=1;}for(int z=26;z<30;z++){int i=z*n+30;e.height[i]=88;e.water[i]=90;e.river[i]=1;}for(int x=0;x<3;x++){int i=50*n+x;e.height[i]=88;e.water[i]=90;e.river[i]=1;}int removed=RiverPuddleCleanup.apply(e,n,62,64);if(removed!=9||RiverPuddleCleanup.wet(e,11*n+11,62)||!RiverPuddleCleanup.wet(e,26*n+30,62)||!RiverPuddleCleanup.wet(e,50*n,62))throw new AssertionError("Removed attached/boundary water or retained isolated puddle: "+removed);System.out.println("PASS: isolated fragment removed; larger water, attached short branch and region boundary water retained");}}
